#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>
#include <limits.h>

#define BASE UINT32_C(1000000000)

typedef struct {
    uint32_t *digits;   /* little-endian base-1,000,000,000 digits */
    size_t len;
    size_t capacity;
} Big;

static void die(void)
{
    fputs("out of memory\n", stderr);
    exit(1);
}

static void reserve(Big *x, size_t needed)
{
    if (needed > x->capacity) {
        size_t capacity = x->capacity ? x->capacity : 1;
        while (capacity < needed) {
            if (capacity > SIZE_MAX / 2) {
                capacity = needed;
                break;
            }
            capacity *= 2;
        }
        uint32_t *p = realloc(x->digits, capacity * sizeof(*p));
        if (!p) die();
        x->digits = p;
        x->capacity = capacity;
    }
}

static void add(Big *result, const Big *a, const Big *b)
{
    size_t n = a->len > b->len ? a->len : b->len;
    reserve(result, n + 1);
    uint64_t carry = 0;
    for (size_t i = 0; i < n; ++i) {
        uint64_t value = carry;
        if (i < a->len) value += a->digits[i];
        if (i < b->len) value += b->digits[i];
        result->digits[i] = (uint32_t)(value % BASE);
        carry = value / BASE;
    }
    if (carry) result->digits[n++] = (uint32_t)carry;
    result->len = n;
}

static void print_big(const Big *x)
{
    if (x->len == 0) {
        puts("0");
        return;
    }
    printf("%" PRIu32, x->digits[x->len - 1]);
    for (size_t i = x->len - 1; i-- > 0;)
        printf("%09" PRIu32, x->digits[i]);
    putchar('\n');
}

int main(int argc, char **argv)
{
    if (argc != 2) {
        fprintf(stderr, "usage: %s N\n", argv[0]);
        return 2;
    }

    char *end;
    errno = 0;
    unsigned long long parsed = strtoull(argv[1], &end, 10);
    if (errno || *argv[1] == '\0' || *end != '\0' || parsed > SIZE_MAX) {
        fputs("N must be a non-negative integer\n", stderr);
        return 2;
    }
    size_t n = (size_t)parsed;

